import requests

BLOCK_SIZE = 16
URL = 'https://auth.ctfatlas.local/verify'

def padding_oracle(cipher_bytes):
    res = requests.post(URL, data={'token': cipher_bytes.hex()})
    # True if valid padding, False if padding error
    return 'Padding Error' not in res.text

def decrypt_block(c_prev, c_curr):
    intermediate = bytearray(BLOCK_SIZE)
    plaintext = bytearray(BLOCK_SIZE)

    for byte_idx in reversed(range(BLOCK_SIZE)):
        pad_val = BLOCK_SIZE - byte_idx
        test_c_prev = bytearray(c_prev)

        # Set previously solved bytes to target padding value
        for k in range(byte_idx + 1, BLOCK_SIZE):
            test_c_prev[k] = intermediate[k] ^ pad_val

        found = False
        for guess in range(256):
            test_c_prev[byte_idx] = guess
            if padding_oracle(test_c_prev + c_curr):
                intermediate[byte_idx] = guess ^ pad_val
                plaintext[byte_idx] = intermediate[byte_idx] ^ c_prev[byte_idx]
                found = True
                break
        if not found:
            print(f'[-] Failed to solve byte {byte_idx}')
    return bytes(plaintext)

